/**
 * A class to build help for an entire 'G' application.  This class will take in a list of
 * module paths and build the help for each module.  To build single modules, call this class
 * with only one module path.
 * <p>
 * Note: Help links must not be absolute.  They can be relative, including <code>. and ..</code>
 * syntax.  Further, they can use the special help system syntax, which is:
 * <ul>
 * 	<li><code><b>help/topics/</b>topicName/Filename.html</code> for referencing help topic files</li>
 *  <li><code><b>help/</b>shared/image.png</code> for referencing image files at paths rooted under
 *                                            the module's root help dir</li>
 * </ul>
 */
public class GHelpBuilder {
	private static readonly string TOC_OUTPUT_FILE_APPENDIX = "_TOC.xml";
	private static readonly string MAP_OUTPUT_FILE_APPENDIX = "_map.xml";
	private static readonly string HELP_SET_OUTPUT_FILE_APPENDIX = "_HelpSet.hs";
	private static readonly string HELP_SEARCH_DIRECTORY_APPENDIX = "_JavaHelpSearch";

	private static readonly string OUTPUT_DIRECTORY_OPTION = "-o";
	private static readonly string MODULE_NAME_OPTION = "-n";
	private static readonly string HELP_PATHS_OPTION = "-hp";
	private static readonly string HELP_PATHS_GENERATED_OPTION = "-hpg";
	private static readonly string DEBUG_SWITCH = "-debug";
	private static readonly string IGNORE_INVALID_SWITCH = "-ignoreinvalid";

	private string outputDirectoryName;
	private string moduleName;
	private Collection<File> dependencyHelpPaths = new();
	private Collection<File> generatedDependencyHelpPaths = new();
	private Collection<File> helpInputDirectories = new();
	private static bool debugEnabled = false;
	private bool ignoreInvalid = false; // TODO: Do actual validation here

