	private void parseArguments(string[] args) {

		for (int i = 0; i < args.length; i++) {
			string opt = args[i];
			if (opt.equals(OUTPUT_DIRECTORY_OPTION)) {
				i++;
				if (i >= args.length) {
					error(OUTPUT_DIRECTORY_OPTION + " requires an argument");
					printUsage();
					Environment.Exit(1);
				}
				outputDirectoryName = args[i];
			}
			else if (opt.equals(MODULE_NAME_OPTION)) {
				i++;
				if (i >= args.length) {
					error(MODULE_NAME_OPTION + " requires an argument");
					printUsage();
					Environment.Exit(1);
				}
				moduleName = args[i];
			}
			else if (opt.equals(HELP_PATHS_OPTION)) {
				i++;
				if (i >= args.length) {
					error(HELP_PATHS_OPTION + " requires an argument");
					printUsage();
					Environment.Exit(1);
				}
				string hp = args[i];
				if (hp.length() > 0) {
					foreach (string p in hp.split(File.pathSeparator)) {
						dependencyHelpPaths.add(new File(p));
					}
				}
			}
			else if (opt.equals(HELP_PATHS_GENERATED_OPTION)) {
				i++;
				if (i >= args.length) {
					error(HELP_PATHS_GENERATED_OPTION + " requires an argument");
					printUsage();
					Environment.Exit(1);
				}
				string hp = args[i];
				if (hp.length() > 0) {
					foreach (string p in hp.split(File.pathSeparator)) {
						generatedDependencyHelpPaths.add(new File(p));
					}
				}
			}
			else if (opt.equals(DEBUG_SWITCH)) {
				debugEnabled = true;
			}
			else if (opt.equals(IGNORE_INVALID_SWITCH)) {
				ignoreInvalid = true;
			}
			else if (opt.startsWith("-")) {
				error("Unknown option " + opt);
				printUsage();
				Environment.Exit(1);
			}
			else {
				// It must just be an input
				helpInputDirectories.add(new File(opt));
			}
		}

		HelpBuildUtils.debug = debugEnabled;

		if (helpInputDirectories.size() == 0) {
			error("Must specify at least one input directory");
			printUsage();
			Environment.Exit(1);
		}
		if (outputDirectoryName == null) {
			error("Missing output directory: " + OUTPUT_DIRECTORY_OPTION + " [output]");
			printUsage();
			Environment.Exit(1);
		}
		if (moduleName == null) {
			error("Missing module name: " + MODULE_NAME_OPTION + " [name]");
			printUsage();
			Environment.Exit(1);
		}

	}

	private static void printUsage() {
		StringBuilder buffy = new StringBuilder();
		// TODO: Complete this once the options are stable

		buffy.append("Usage: ");
		buffy.append(typeof(GHelpBuilder).getName()).append(" [-options] [inputs...]\n");
		buffy.append("          (to build help for a Ghidra module)\n");
		buffy.append("where options include:\n");
		buffy.append("    ").append(OUTPUT_DIRECTORY_OPTION).append(" <output directory>\n");
		buffy.append(
			"                  REQUIRED to specify the output location of the built help\n");
		buffy.append("    ").append(DEBUG_SWITCH).append("        to enable debugging output\n");
		buffy.append("    ").append(IGNORE_INVALID_SWITCH).append("\n");
		buffy.append("                  to continue despite broken links and anchors\n");

		error(buffy.toString());
	}

